package main

import "fmt"

func queens(board [][]rune) int {
	cont := 0
	for i := range board {
		for j := range board[i] {
			if board[i][j] == 'F' {
				board[i][j] = 'Q'
				invalidatePos(board, i, j)
				cont++
				println(board)
			}
		}
	}

	return cont
}

func invalidatePos(board [][]rune, i, j int) {
	if i < 0 || j < 0 || i >= len(board) || j >= len(board[0]) || board[i][j] == '#' {
		return
	}

	board[i][j] = '#'

	invalidatePos(board, i+1, j)
	invalidatePos(board, i-1, j)
	invalidatePos(board, i, j+1)
	invalidatePos(board, i, j-1)
}

func main() {
	var n int
	fmt.Scan(&n)
	board := make([][]rune, n)
	for i := range board {
		board[i] = make([]rune, n)
	}

	for i := range board {
		for j := range board[i] {
			board[i][j] = 'F'
		}
	}
	fmt.Println(board)
	fmt.Println(queens(board))
}
